<script setup lang="ts">
/**
 * A picture opened large over the page (`design/components/lightbox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/lightbox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  cloneVNode,
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  useId,
  useTemplateRef,
  watch,
} from 'vue'

import * as zag from '@zag-js/dialog'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  agentMember,
  definedProps,
  modalFocusTarget,
  slottedElements,
  useDirection,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/lightbox.module.css'
import Button from '../controls/Button.vue'
import Image from '../structure/Image.vue'

export interface LightboxImage {
  src: string
  alt: string
}

export interface LightboxMessages {
  close: string
  previous: string
  next: string
  position: (position: number, count: number) => string
}

export interface LightboxProps {
  /**
   * The picture shown first while the lightbox holds the position. Defaults to 0.
   */
  defaultIndex?: number
  defaultOpen?: boolean
  /**
   * The pictures in reading order. An empty list opens nothing.
   */
  images: LightboxImage[]
  /**
   * The picture shown, counted from 0. Controlled, as in Carousel.
   */
  index?: number
  /**
   * The dialog's accessible name, such as "Attachment preview". It is not drawn.
   */
  label: string
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  messages?: LightboxMessages
  open?: boolean
}

defineOptions({ name: 'Lightbox', inheritAttrs: false })

const props = withDefaults(defineProps<LightboxProps>(), {
  defaultIndex: 0,
  defaultOpen: undefined,
  messages: () => ({
    close: 'Close',
    previous: 'Previous picture',
    next: 'Next picture',
    position: (position, count) => `${position} of ${count}`,
  }),
  open: undefined,
})
const emit = defineEmits<{ indexChange: [index: number]; openChange: [open: boolean] }>()
defineSlots<{ trigger?: (props: Record<string, never>) => unknown }>()
const uid = useId()
const opener = ref(null as HTMLElement | null)
const mirror = ref(props.defaultIndex)
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const within = computed(
  () => (at: number) => Math.min(Math.max(at, 0), Math.max(props.images.length - 1, 0)),
)
const shown = computed(() => within.value(props.index ?? mirror.value))
const several = computed(() => props.images.length > 1)
const current = computed(() => props.images.slice(shown.value, shown.value + 1))
const travel = computed(() => (to: number) => {
  if (to < 0 || to >= props.images.length || to === shown.value) return
  mirror.value = to
  emit('indexChange', to)
})
const keyDown = computed(() => (event: KeyboardEvent) => {
  if (!several.value || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return
  const rtl = getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl'
  const forward = rtl ? 'ArrowLeft' : 'ArrowRight'
  const back = rtl ? 'ArrowRight' : 'ArrowLeft'
  if (event.key !== forward && event.key !== back) return
  event.preventDefault()
  travel.value(event.key === forward ? shown.value + 1 : shown.value - 1)
})
const focusAfterMove = computed(() => () => {
  if (panel.value === null) return
  const previous = panel.value.querySelector<HTMLButtonElement>(
    '[data-lightbox-part="previous"] button',
  )
  const next = panel.value.querySelector<HTMLButtonElement>('[data-lightbox-part="next"] button')
  const active = document.activeElement
  const lost =
    active === null ||
    active === document.body ||
    ((active === previous || active === next) && (active as HTMLButtonElement).disabled)
  if (!lost) return
  const other = [previous, next].find((button) => button !== null && !button.disabled)
  other?.focus()
})
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open === undefined ? undefined : props.open && props.images.length > 0,
    defaultOpen:
      props.defaultOpen === undefined ? undefined : props.defaultOpen && props.images.length > 0,
    initialFocusEl: () => modalFocusTarget(panel.value, 'primary'),
    finalFocusEl: () => opener.value,
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const openFrom = computed(() => (event?: Event) => {
  if (props.images.length === 0) return
  if (event?.currentTarget instanceof HTMLElement) opener.value = event.currentTarget
  api.value.setOpen(true)
})
const scrimPresent = usePresence(() => api.value.open, scrim, 'dialog.scrim')
const panelPresent = usePresence(() => api.value.open, panel, 'dialog.panel')
const effect1 = () => {
  focusAfterMove.value()
}
watch(() => shown.value, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Lightbox',
    element: () => panel.value,
    state: () => ({
      open: api.value.open,
      index: shown.value,
      images: props.images.map((image) => ({ alt: image.alt })),
    }),
    actions: {
      close: () => api.value.open && api.value.setOpen(false),
      next: () =>
        (() => {
          if (!api.value.open) throw new Error('The lightbox is closed.')
          if (shown.value === props.images.length - 1) throw new Error('This is the last picture.')
          travel.value(shown.value + 1)
        })(),
      previous: () =>
        (() => {
          if (!api.value.open) throw new Error('The lightbox is closed.')
          if (shown.value === 0) throw new Error('This is the first picture.')
          travel.value(shown.value - 1)
        })(),
    },
    withholds: () => panel.value,
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <template v-for="(node, at) in slottedElements($slots.trigger)" :key="at">
    <component :is="cloneVNode(node, definedProps({ onClick: openFrom }))" />
  </template>
  <Teleport to="body">
    <!-- scrim -->
    <div
      v-if="scrimPresent"
      ref="scrim"
      v-bind="api.getBackdropProps()"
      :class="styles.scrim"
      :hidden="undefined"
      @click="api.setOpen(false)"
    />
    <div v-if="panelPresent" v-bind="api.getPositionerProps()" :class="styles.positioner">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.panel"
        :hidden="undefined"
        data-member="lightbox"
        @keydown="keyDown($event)"
      >
        <!-- title -->
        <h2 v-bind="api.getTitleProps()" :class="styles.title">
          {{ label }}
        </h2>
        <!-- stage -->
        <div :class="styles.stage">
          <template v-for="picture in current" :key="shown">
            <Image :src="picture.src" :alt="picture.alt" loading="eager" />
          </template>
        </div>
        <template v-if="several">
          <!-- previous -->
          <div :class="styles.previous" data-lightbox-part="previous">
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              :iconOnly="true"
              icon="previous"
              :label="messages.previous"
              :disabled="shown === 0"
              @click="travel(shown - 1)"
            />
          </div>
          <!-- next -->
          <div :class="styles.next" data-lightbox-part="next">
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              :iconOnly="true"
              icon="next"
              :label="messages.next"
              :disabled="shown === images.length - 1"
              @click="travel(shown + 1)"
            />
          </div>
          <!-- position -->
          <p :class="styles.position" role="status">
            {{ messages.position(shown + 1, images.length) }}
          </p>
        </template>
        <!-- close -->
        <div :class="styles.close" data-dialog-part="close">
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            :iconOnly="true"
            icon="close"
            :label="messages.close"
            @click="api.setOpen(false)"
          />
        </div>
      </div>
    </div>
  </Teleport>
</template>
